-- WITHOUT procedural abstraction (code duplicated 5 times):
-- For class 1:
IF(score1 ≥ 90) { grade1 ← "A" }
ELSE { IF(score1 ≥ 80) { grade1 ← "B" } ELSE { grade1 ← "C" } }

-- For class 2:
IF(score2 ≥ 90) { grade2 ← "A" }
ELSE { IF(score2 ≥ 80) { grade2 ← "B" } ELSE { grade2 ← "C" } }

-- ...repeated 3 more times for classes 3, 4, 5...
-- If the A threshold changes to 93, must update in 5 DIFFERENT places
-- Easy to miss one → bug!

-- WITH procedural abstraction (logic in one place, reused 5 times):
PROCEDURE getLetterGrade(score)
{
   IF(score ≥ 90) { RETURN "A" }
   IF(score ≥ 80) { RETURN "B" }
   RETURN "C"
}

-- Used for all 5 classes:
grade1 ← getLetterGrade(score1)
grade2 ← getLetterGrade(score2)
grade3 ← getLetterGrade(score3)
grade4 ← getLetterGrade(score4)
grade5 ← getLetterGrade(score5)
-- If A threshold changes to 93: update ONE line in the procedure
-- ALL 5 calls automatically use the updated logic
